NativeHeapTraceRegistry::NativeHeapTraceRegistry(){page_=VirtualAlloc(nullptr,4096,MEM_RESERVE|MEM_COMMIT,PAGE_READWRITE);if(!page_)throw std::runtime_error("Trace registry memory unavailable");std::memset(page_,0xa5,4096);std::memset(static_cast<std::byte*>(page_)+0x40,0,8);std::memset(static_cast<std::byte*>(page_)+0x80,0,512);}
NativeHeapTraceRegistry::~NativeHeapTraceRegistry(){owners_.fill(nullptr);if(page_)VirtualFree(page_,0,MEM_RELEASE);}
void NativeHeapTraceRegistry::query(std::span<std::byte> info)const{if(info.size()!=32)throw std::invalid_argument("Trace info extent32 required");NativeHeapTraceInfo original{};std::memcpy(&original,info.data(),32);if(original.size!=32)throw std::invalid_argument("Trace info size32 required");const auto a=reinterpret_cast<std::uintptr_t>(info.data()),b=reinterpret_cast<std::uintptr_t>(page_);if(a<b+4096&&b<a+32)throw std::invalid_argument("Trace info/page alias unsupported");std::lock_guard guard(lock_);original.get_segment_info=0;original.mask=reinterpret_cast<std::uint64_t*>(static_cast<std::byte*>(page_)+0x40);original.table=reinterpret_cast<std::uint64_t*>(static_cast<std::byte*>(page_)+0x80);std::memcpy(info.data(),&original,32);}
unsigned NativeHeapTraceRegistry::insert(std::shared_ptr<SystemPoolBackend> b){if(!b||b->capacity!=0x4000||b->heap.header_token!=0x60000020)throw std::invalid_argument("Actual bounded backend required");auto backing=b->memory.bytes();if(backing.size()!=0x4000||b->heap.header_token<reinterpret_cast<std::uint64_t>(backing.data())||b->heap.header_token-reinterpret_cast<std::uint64_t>(backing.data())+0x3b0>backing.size())throw std::invalid_argument("Actual backed header required");std::uint64_t signature{};std::memcpy(&signature,backing.data()+b->heap.header_token-reinterpret_cast<std::uint64_t>(backing.data())+0x38,8);if(signature!=0&&signature!=0x58585858)throw std::invalid_argument("Verified mspace signature required");std::lock_guard guard(lock_);for(auto& owner:owners_)if(owner==b)throw std::invalid_argument("Duplicate trace heap");unsigned index=0;while(index<64&&owners_[index])++index;if(index==64)throw std::invalid_argument("Trace registry full");auto* mask=reinterpret_cast<std::uint64_t*>(static_cast<std::byte*>(page_)+0x40);auto* table=reinterpret_cast<std::uint64_t*>(static_cast<std::byte*>(page_)+0x80);owners_[index]=std::move(b);table[index]=owners_[index]->heap.header_token;*mask|=std::uint64_t{1}<<index;return index;}
void NativeHeapTraceRegistry::erase(unsigned index){if(index>=64)throw std::invalid_argument("Trace index invalid");std::shared_ptr<SystemPoolBackend> retired;{std::lock_guard guard(lock_);if(!owners_[index])throw std::invalid_argument("Trace entry absent");auto* mask=reinterpret_cast<std::uint64_t*>(static_cast<std::byte*>(page_)+0x40);auto* table=reinterpret_cast<std::uint64_t*>(static_cast<std::byte*>(page_)+0x80);*mask&=~(std::uint64_t{1}<<index);table[index]=0;retired=std::move(owners_[index]);}}
std::array<std::byte,4096> NativeHeapTraceRegistry::snapshot()const{std::lock_guard guard(lock_);std::array<std::byte,4096> bytes{};std::memcpy(bytes.data(),page_,4096);return bytes;}
